using System.Threading.Channels;
using Microsoft.EntityFrameworkCore;
namespace AcSimulator.Api.Infrastructure;
public sealed class ReportQueue { private readonly Channel<Guid> _queue=Channel.CreateBounded<Guid>(new BoundedChannelOptions(100){FullMode=BoundedChannelFullMode.DropWrite}); public bool Enqueue(Guid id)=>_queue.Writer.TryWrite(id); public IAsyncEnumerable<Guid> ReadAll(CancellationToken ct)=>_queue.Reader.ReadAllAsync(ct); }
public sealed class ReportWorker(IServiceScopeFactory scopes,ReportQueue queue,IWebHostEnvironment env,ILogger<ReportWorker> log):BackgroundService {
  protected override async Task ExecuteAsync(CancellationToken ct){await foreach(var id in queue.ReadAll(ct)){using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var report=await db.Reports.FindAsync([id],ct);if(report is null)continue;try{report.Status="processing";await db.SaveChangesAsync(ct);var project=await db.Projects.IgnoreQueryFilters().SingleAsync(x=>x.Id==report.ProjectId,ct);var result=report.ScenarioId is { } scenarioId?await db.Scenarios.Where(x=>x.Id==scenarioId&&x.ProjectId==project.Id).Select(x=>x.ResultSummaryJson).SingleOrDefaultAsync(ct):null;var bytes=SimplePdf.Create(project.Name,project.ConfigJson,result);var dir=Path.Combine(env.WebRootPath??Path.Combine(env.ContentRootPath,"wwwroot"),"reports");Directory.CreateDirectory(dir);var file=$"{id:N}.pdf";await File.WriteAllBytesAsync(Path.Combine(dir,file),bytes,ct);report.Status="succeeded";report.FileUrl=$"/api/projects/{project.Id}/reports/{id}/file";report.CompletedAt=DateTime.UtcNow;}catch(Exception ex){log.LogError(ex,"Report {ReportId} failed",id);report.Status="failed";report.Error="Report generation failed. Retry is safe.";report.CompletedAt=DateTime.UtcNow;}await db.SaveChangesAsync(ct);}}
}
internal static class SimplePdf { public static byte[] Create(string name,string config,string? result){using var doc=System.Text.Json.JsonDocument.Parse(config);var root=doc.RootElement;var rooms=root.TryGetProperty("rooms",out var roomList)?roomList.GetArrayLength():0;var acUnits=root.TryGetProperty("acUnits",out var acList)?acList.GetArrayLength():0;var environment=root.GetProperty("environment");var lines=new List<string>{"AC Thermal Studio - Simulation report",$"Project: {name}",$"Generated: {DateTime.UtcNow:O}","Engine: thermal-visual-2.0",$"Rooms: {rooms} | AC units: {acUnits}",$"Outside / target: {environment.GetProperty("outsideTempC").GetDouble():0.0} / {environment.GetProperty("targetTempC").GetDouble():0.0} C"};if(result is not null){using var metrics=System.Text.Json.JsonDocument.Parse(result);var m=metrics.RootElement;if(m.TryGetProperty("heatLoadKw",out var load))lines.Add($"Estimated heat load: {load.GetDouble():0.00} kW");if(m.TryGetProperty("averageAt60C",out var average))lines.Add($"Average at result point: {average.GetDouble():0.0} C");if(m.TryGetProperty("comfortPercent",out var comfort))lines.Add($"Comfort area: {comfort.GetDouble():0}%");}foreach(var room in roomList.EnumerateArray())lines.Add($"Room: {room.GetProperty("name").GetString()} | {room.GetProperty("lengthM").GetDouble():0.0} x {room.GetProperty("widthM").GetDouble():0.0} x {room.GetProperty("heightM").GetDouble():0.0} m");lines.Add("Approximate visual model - not a real measurement or certified HVAC design result.");static string Safe(string value)=>value.Replace("\\","\\\\").Replace("(","\\(").Replace(")","\\)").Select(c=>c<=127?c:'?').Aggregate(new System.Text.StringBuilder(),(b,c)=>b.Append(c)).ToString();var content="BT /F1 11 Tf 48 760 Td "+string.Join(" Tj 0 -20 Td ",lines.Take(30).Select(x=>$"({Safe(x)})"))+" Tj ET";var objects=new[]{"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",$"<< /Length {System.Text.Encoding.ASCII.GetByteCount(content)} >>\nstream\n{content}\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>"};using var ms=new MemoryStream();using var w=new StreamWriter(ms,System.Text.Encoding.ASCII,leaveOpen:true);w.Write("%PDF-1.4\n");w.Flush();var offsets=new List<long>{0};for(var i=0;i<objects.Length;i++){offsets.Add(ms.Position);w.Write($"{i+1} 0 obj\n{objects[i]}\nendobj\n");w.Flush();}var xref=ms.Position;w.Write($"xref\n0 {objects.Length+1}\n0000000000 65535 f \n");foreach(var o in offsets.Skip(1))w.Write($"{o:0000000000} 00000 n \n");w.Write($"trailer << /Size {objects.Length+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF");w.Flush();return ms.ToArray();} }
